cmd:
cat > /etc/nginx/sites-available/git-deploy << 'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/nginx.crt;
    ssl_certificate_key /etc/nginx/ssl/nginx.key;

    # Disable SSL verification warnings for local testing
    ssl_verify_client off;

    location / {
        root /var/www/main;
        index index.html;
    }

    location /dev {
        alias /var/www/dev;
        index index.html;
    }
}
EOF

# Enable the site
ln -sf /etc/nginx/sites-available/git-deploy /etc/nginx/sites-enabled/git-deploy

# Remove default config if it exists and conflicts
rm -f /etc/nginx/sites-enabled/default

# Test nginx config
nginx -t 2>&1
